window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-66fad5e1166b59b5"]={"versions": [{"id": "FIG-66fad5e1166b59b5", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Konfigurationsstruktur des AUTOSAR FlexRay Transport Protocol (FrTp). Das Diagramm modelliert die strukturelle Beziehung und Kardinalität zwischen logischen Kanälen (<code>Channel</code>) und Transportverbindungen (<code>Connection</code>) innerhalb der Kommunikationsinfrastruktur des FrTp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Channel</strong>: Repräsentiert einen logischen Kommunikationskanal im FrTp mit aggregierten Kanaleigenschaften (<code>Properties of the channel</code>).\n</li><li><strong>Connection</strong>: Repräsentiert eine Transportverbindung mit Verbindungseigenschaften (<code>Properties of the connection</code>).\n<ul class=\"fig-list\"><li>Attribut: <code>+ FRTP_SDUID: PduIdType</code> (eindeutiger Bezeichner der Service Data Unit).\n</li></ul>\n</li><li><strong>Beziehung / Komposition</strong>:\n<ul class=\"fig-list\"><li>Kompositionsbeziehung (schwarze Raute) von <code>Channel</code> zu <code>Connection</code>.\n</li><li>Rollenbezeichnung und Multiplizität am Kanalende: <code>+is contained in 1</code>.\n</li><li>Rollenbezeichnung und Multiplizität am Verbindungsende: <code>+contains 1..*</code>.\n</li><li>Ein <code>Channel</code> enthält somit mindestens eine oder mehrere (<code>1..*</code>) Instanzen von <code>Connection</code>; jede <code>Connection</code> ist genau einem (<code>1</code>) <code>Channel</code> fest zugeordnet.\n</li></ul>\n</li><li><strong>Kommentar / Invariante</strong>:\n<ul class=\"fig-list\"><li>Angeheftete UML-Notiz an <code>Connection</code> bezüglich des Attributs <code>FRTP_SDUID</code>: „FRTP_SDUID Invariant: the value of FRTP_SDUID shall be unique for each connection.“\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Interaktionsdynamik. Zur Laufzeit bzw. Konfigurationszeit bildet jeder <code>Channel</code> den übergeordneten Kontext für ein oder mehrere gemultiplexte oder parallel verwaltete <code>Connection</code>-Objekte, über die segmentierte FrTp-Übertragungen anhand der eindeutigen <code>FRTP_SDUID</code> adressiert und geroutet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Konfigurationsintegrität: Ein FrTp-Kanal muss zwingend mindestens eine Verbindung aufweisen (<code>1..*</code>), eine verwaiste oder kanallose Verbindung existiert im Datenmodell nicht (strenge Komposition, Kardinalität <code>1</code>).\n</li><li>Eindeutigkeitsanforderung: Die <code>FRTP_SDUID</code> vom Typ <code>PduIdType</code> fungiert als primärer Schlüssel/Deskriptor und muss über alle <code>Connection</code>-Entitäten hinweg strikt eindeutig konfiguriert werden, um eine eindeutige Zuordnung der oberen PDU-Schichten (z. B. PduR) zum FrTp zu gewährleisten.\n</li></ul>"}, {"id": "FIG-51c919a14d50238a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Konfigurationsstruktur des AUTOSAR FlexRay Transport Protocol (FrTp). Das Diagramm modelliert die strukturelle Beziehung und Kardinalität zwischen logischen Kanälen (<code>Channel</code>) und Transportverbindungen (<code>Connection</code>) innerhalb der Kommunikationsinfrastruktur des FrTp.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Channel</strong>: Repräsentiert einen logischen Kommunikationskanal im FrTp mit aggregierten Kanaleigenschaften (<code>Properties of the channel</code>).\n</li><li><strong>Connection</strong>: Repräsentiert eine Transportverbindung mit Verbindungseigenschaften (<code>Properties of the connection</code>).\n<ul class=\"fig-list\"><li>Attribut: <code>+ FRTP_SDUID: PduIdType</code> (eindeutiger Bezeichner der Service Data Unit).\n</li></ul>\n</li><li><strong>Beziehung / Komposition</strong>:\n<ul class=\"fig-list\"><li>Kompositionsbeziehung (schwarze Raute) von <code>Channel</code> zu <code>Connection</code>.\n</li><li>Rollenbezeichnung und Multiplizität am Kanalende: <code>+is contained in 1</code>.\n</li><li>Rollenbezeichnung und Multiplizität am Verbindungsende: <code>+contains 1..*</code>.\n</li><li>Ein <code>Channel</code> enthält somit mindestens eine oder mehrere (<code>1..*</code>) Instanzen von <code>Connection</code>; jede <code>Connection</code> ist genau einem (<code>1</code>) <code>Channel</code> fest zugeordnet.\n</li></ul>\n</li><li><strong>Kommentar / Invariante</strong>:\n<ul class=\"fig-list\"><li>Angeheftete UML-Notiz an <code>Connection</code> bezüglich des Attributs <code>FRTP_SDUID</code>: „FRTP_SDUID Invariant: the value of FRTP_SDUID shall be unique for each connection.“\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauf- oder Interaktionsdynamik. Zur Laufzeit bzw. Konfigurationszeit bildet jeder <code>Channel</code> den übergeordneten Kontext für ein oder mehrere gemultiplexte oder parallel verwaltete <code>Connection</code>-Objekte, über die segmentierte FrTp-Übertragungen anhand der eindeutigen <code>FRTP_SDUID</code> adressiert und geroutet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Konfigurationsintegrität: Ein FrTp-Kanal muss zwingend mindestens eine Verbindung aufweisen (<code>1..*</code>), eine verwaiste oder kanallose Verbindung existiert im Datenmodell nicht (strenge Komposition, Kardinalität <code>1</code>).\n</li><li>Eindeutigkeitsanforderung: Die <code>FRTP_SDUID</code> vom Typ <code>PduIdType</code> fungiert als primärer Schlüssel/Deskriptor und muss über alle <code>Connection</code>-Entitäten hinweg strikt eindeutig konfiguriert werden, um eine eindeutige Zuordnung der oberen PDU-Schichten (z. B. PduR) zum FrTp zu gewährleisten.\n</li></ul>"}], "trans": [{"from": "FIG-66fad5e1166b59b5", "to": "FIG-51c919a14d50238a", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
